// Auth usage examples:
// const { user } = await auth.signIn()           - sign in with popup (default scopes: openid email profile offline_access)
// await auth.signIn({ scope: 'openid email profile offline_access' }) - with refresh token
// auth.isSignedIn()                               - check if signed in (sync, no network call)
// const user = await auth.getUser()               - get current user (auto-refreshes token)
// user.userId / user.email / user.name            - user fields (email/name require matching scopes)
// await auth.signOut()                            - sign out and clear tokens
// After signIn, api.get/post/put/delete auto-attach Authorization: Bearer <token>
// signIn errors: error.code = 'popup_blocked' | 'popup_closed' | 'auth_error'

// Auth apps should ask for app-owned Terms and Privacy docs or links.
// If the user provides HTTPS legal links, set termsUrl/privacyUrl to those links.
// If the user will upload legal docs, use optional resource_requirements slots (required:false) for public/resources/terms-and-conditions.pdf and public/resources/privacy-policy.pdf, and point termsUrl/privacyUrl at those paths.
// If no legal links/files are provided, still deploy; missing legal docs fall back to placeholder legal links until real app legal links are supplied.

frontend.types:
/** Authenticated user information */
export interface AuthUser {
    /** Stable AppDeploy user ID (UUID) */
    userId: string;
    /** User's email address (requires 'email' scope) */
    email?: string;
    /** User's display name (requires 'profile' scope) */
    name?: string;
    /** User's profile picture URL (requires 'profile' scope) */
    picture?: string;
    /** Space-separated list of granted scopes */
    scope: string;
}

/** Sign-in options */
export interface SignInOptions {
    /** Space-separated list of scopes to request (default: "openid email profile offline_access") Do not include 'offline_access' if you intentionally do not want refresh tokens. */
    scope?: string;
}

/** Sign-in result */
export interface SignInResult {
    /** The authenticated user */
    user: AuthUser;
    /** Access token (automatically attached to API requests) */
    accessToken: string;
    /** Token expiration time in seconds */
    expiresIn: number;
}

/** Authentication API */
export interface AuthAPI {
    /**
     * Opens a popup for user sign-in.
     * Returns the authenticated user on success, or throws on failure/cancel.
     * Error codes: 'popup_blocked' (browser blocked the popup), 'popup_closed' (user closed before completing), 'auth_error' (authentication failed).
     */
    signIn(options?: SignInOptions): Promise<SignInResult>;

    /**
     * Gets the currently authenticated user, or null if not signed in.
     * Automatically refreshes expired access tokens if a refresh token exists.
     */
    getUser(): Promise<AuthUser | null>;

    /**
     * Gets the current access token, or null if not signed in.
     * Automatically refreshes expired tokens if a refresh token exists.
     */
    getAccessToken(): Promise<string | null>;

    /**
     * Signs out the current user and clears stored tokens.
     */
    signOut(): Promise<void>;

    /**
     * Returns true if the user is signed in (has a valid or refreshable token).
     */
    isSignedIn(): boolean;
}

export const auth: AuthAPI;

